#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 10
static int parent[MAXN];
static int rank_arr[MAXN];

static int find_set(int x) {
    if (parent[x] != x) {
        parent[x] = find_set(parent[x]);
    }
    return parent[x];
}

static void union_set(int a, int b) {
    int ra = find_set(a);
    int rb = find_set(b);
    if (ra == rb) return;
    if (rank_arr[ra] < rank_arr[rb]) {
        parent[ra] = rb;
    } else if (rank_arr[ra] > rank_arr[rb]) {
        parent[rb] = ra;
    } else {
        parent[rb] = ra;
        rank_arr[ra]++;
    }
    printf("UNION %d %d\n", a, b);
}

int main(int argc, char **argv) {
    // initialize union‑find structure for elements 0‑9
    for (int i = 0; i < MAXN; ++i) {
        parent[i] = i;
        rank_arr[i] = 0;
    }

    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    int i = 1; // start after program name
    while (i < argc) {
        char *cmd = argv[i];
        if (cmd[0] == 'U') { // union command, expects two numbers
            if (i + 2 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[i+1], NULL, 10);
            long b = strtol(argv[i+2], NULL, 10);
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) {
                puts("INVALID");
            } else {
                union_set((int)a, (int)b);
            }
            i += 3; // command + two arguments
        } else if (cmd[0] == 'F') { // find command, expects one number
            if (i + 1 >= argc) { puts("INVALID"); break; }
            long x = strtol(argv[i+1], NULL, 10);
            if (x < 0 || x >= MAXN) {
                puts("INVALID");
            } else {
                int root = find_set((int)x);
                printf("FIND %ld=%d\n", x, root);
            }
            i += 2; // command + one argument
        } else if (cmd[0] == 'C') { // connectivity check, expects two numbers
            if (i + 2 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[i+1], NULL, 10);
            long b = strtol(argv[i+2], NULL, 10);
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) {
                puts("INVALID");
            } else {
                int ra = find_set((int)a);
                int rb = find_set((int)b);
                puts(ra == rb ? "YES" : "NO");
            }
            i += 3; // command + two arguments
        } else {
            puts("INVALID");
            i++; // skip unknown command
        }
    }
    return 0;
}
